function DIAGONAL_ESCAPE(f[0..N-1][0..N-1], a):    # a >= 2
    for i in 0..N-1:
        g[i] <- (f[i][i] + 1) mod a
    return g

function CERTIFY(f, g):
    for i in 0..N-1:
        if f[i] == g: return False
    return True   # g escapes every description

function SMALLEST_N(b, k):
    budget <- b^k;  N <- 0;  power <- 1
    while not (budget < power):
        N <- N + 1;  power <- power * 3
    return N

function FINITE_JUMP_HOLDS(N):
    comp <- 3 ^ (N * 3^N)          # oracle_comp_card
    return 3^N < comp              # oracle_comp_jump

